#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    size_t pos = s.find("dot", 1);
    while (pos != std::string::npos) {
        s.replace(pos, 3, ".");
        pos = s.find("dot", pos + 1);
    }
    size_t at_pos = s.find("at", 1);
    if (at_pos != std::string::npos) {
        s.replace(at_pos, 2, "@");
    }
    std::cout << s << std::endl;
    return 0;
}
